import test from 'node:test';import assert from 'node:assert/strict';import {comfortSettings,readComfort,checkpointValue,routeProgress} from '../player-comfort.js';
test('comfort settings respect reduced motion and bound brightness without overriding explicit choices',()=>{assert.deepEqual(comfortSettings({},true),{brightness:1,screenShake:false,steadyLighting:true});assert.equal(comfortSettings({brightness:99}).brightness,1.3);assert.equal(comfortSettings({brightness:-2}).brightness,.8);assert.equal(comfortSettings({screenShake:true},true).screenShake,true);assert.equal(readComfort({getItem(){throw Error('blocked')}},true).steadyLighting,true);});
test('busy saves retain a detached pre-interaction checkpoint instead of half-completed choices',()=>{const stable={world:{gold:3,mode:'field'}},current={world:{gold:99,mode:'dialog'}};const value=checkpointValue({current,stable,busy:true});assert.equal(value.world.gold,3);value.world.gold=8;assert.equal(stable.world.gold,3);assert.equal(checkpointValue({current,stable:null,busy:true}),null);assert.equal(checkpointValue({current,stable,busy:false}).world.gold,99);});
test('blocked tap routes time out but ordinary travel resets the blocked timer',()=>{let p={x:1,y:1,blocked:0};for(let i=0;i<16;i++)p=routeProgress(p,{x:1,y:1},.1);assert.ok(p.blocked>1.5);assert.equal(routeProgress(p,{x:1.03,y:1},.1).blocked,0);});
